import{_ as t}from"./chunks/settings-robot.pc.en.DW3gmNOs.js";import{_ as o,o as a,c as d,a5 as n}from"./chunks/framework.BYXPg_yw.js";const s="/RBQ/nightly/images/app/settings-app.pc.en.png",b=JSON.parse('{"title":"Settings","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/settings.md","filePath":"manual/gui/settings.md","lastUpdated":1792759058000}'),i={name:"manual/gui/settings.md"};function r(c,e,l,h,p,g){return a(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Open settings with the <code>Settings</code> tile on the hub. All sections sit as chips across the top — icons only on a phone — in two groups. The title reads <code>Settings</code> with the robot&#39;s name and serial, the device and the app version.</p><ul><li><strong>Robot sections</strong> belong to the selected robot: <code>Payload setup</code>. They open even without a robot, but anything that acts on the robot needs it connected. While the in-app simulator is selected they are dimmed.</li><li><strong>App sections</strong> belong to this device: <code>Gamepad</code>, <code>App settings</code>. They always open.</li></ul><p>On every settings screen the logo at the top left opens the screen menu, the hub included, and the gamepad button next to it goes straight to the control screen. That button works only while a robot is connected or the sim is running.</p><ul><li>Connecting to a robot is done from the robot list on the hub — see <a href="/RBQ/nightly/manual/gui/connection.html">Connection</a>.</li><li><code>Gamepad</code> is covered in <a href="/RBQ/nightly/manual/gui/gamepad.html">Gamepad</a>.</li><li><code>Power / System</code>, <code>Calibration</code>, <code>Robot Check</code> and <code>Software update</code> are on the <a href="/RBQ/nightly/manual/gui/maintenance.html">Maintenance</a> screen.</li></ul><p>This page covers <code>Payload setup</code> and <code>App settings</code>. Operators can use all of them, and rows that need developer mode are marked.</p><h2 id="robot-parameters" tabindex="-1">Payload setup <a class="header-anchor" href="#robot-parameters" aria-label="Permalink to &quot;Payload setup {#robot-parameters}&quot;">​</a></h2><p><img src="'+t+'" alt="Robot parameters section"></p><p><code>Payload Configuration</code> describes what is mounted on the robot so the walking dynamics can account for it.</p><ol><li>The robot reports 13 payload slots. Check a slot to mark it as mounted and enter its mass and center of mass (X, Y, Z).</li><li>The footer shows the total mass and combined center of mass, and warns when the total exceeds the limit.</li><li>Press <code>Set Payload</code> and confirm with <code>Apply</code> (<code>Get</code> re-reads the slots from the robot and discards your edits). The confirmation shows the number of mounted slots and the totals; unchecked slots are sent with mass 0. The new values reach the walking dynamics right away, ramped in over one to two seconds.</li></ol><p><code>Help</code> expands a short guide above the table. Robots without the payload slot API show a notice asking for a robot software update instead.</p><h2 id="app-settings" tabindex="-1">App settings <a class="header-anchor" href="#app-settings" aria-label="Permalink to &quot;App settings&quot;">​</a></h2><p><img src="'+s+'" alt="App settings section"></p><p>These settings belong to the app, not the robot.</p><table tabindex="0"><thead><tr><th>Row</th><th>Options</th></tr></thead><tbody><tr><td><code>Theme</code></td><td><code>Dark</code> / <code>Light</code></td></tr><tr><td><code>Language / 언어</code></td><td><code>Korean</code> / <code>English</code> — applies immediately</td></tr><tr><td><code>Joystick sensitivity</code></td><td>Slider — input response curve</td></tr><tr><td><code>Keep screen on</code></td><td>Toggle — keeps the screen awake while controlling</td></tr><tr><td><code>Deadzone</code></td><td>Slider — center range ignored by the joystick</td></tr><tr><td><code>Gyro widget</code></td><td>Toggle — roll/pitch attitude display</td></tr><tr><td><code>Fullscreen</code></td><td>Toggle — browser only</td></tr><tr><td><code>Low-signal warning</code></td><td>Toggle — top warning banner when Wi-Fi signal drops below <code>Warning threshold</code> (slider, shown while enabled)</td></tr><tr><td><code>Warning beep (Notify BEEP)</code></td><td>Toggle — short beep on warnings (web only)</td></tr><tr><td><code>Low battery beep</code></td><td>Toggle — beeps when the robot battery is low; <code>Warning beep (Notify BEEP)</code> must be on (web only)</td></tr><tr><td><code>UI scale</code></td><td>Desktop app only — <code>Auto</code>, 100 % to 200 %</td></tr><tr><td><code>Auto update</code></td><td>Toggle, off by default — when new robot software is released, the app asks whether to download it to this device; you then install it on the robot from <code>Maintenance</code> › <code>Software update</code>. A manually installed app (APK, AppImage) is also offered its own update. The question waits until you leave the control screen. If you cancel, that version is not offered again. Not shown in the browser</td></tr></tbody></table><h3 id="developer-mode" tabindex="-1">Developer mode <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;Developer mode {#developer-mode}&quot;">​</a></h3><p>The <code>Developer mode</code> toggle is in the profile menu — the round button at the top right. As a guest, turn on <code>Developer mode</code> and enter the password. Turning it off puts you back at the operator level. While you are logged in with an access code (<code>Log in with access code</code> in the same menu) the toggle is not shown, because the account decides the level.</p><p>Developer mode adds the developer sections of <code>Maintenance</code>, the developer rows above, and the <code>Position control</code> group in the <code>Select motion</code> grid.</p>',18)])])}const w=o(i,[["render",r]]);export{b as __pageData,w as default};
